using UnityEngine;
using Flynn.Events;

/// <summary>
/// Right-click throw for the wrench. Tap = short throw; hold to charge for a longer
/// throw (distance scales min→max with charge). Spawns a ThrownWrench projectile that
/// flies to the target, hovers, then boomerangs back to the player and is caught.
/// Only one throw may be airborne at a time. Exposes IsCharging / ChargeNormalized /
/// IsAirborne for the aim reticle and the swing controller.
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class WrenchThrowController : MonoBehaviour
{
    [SerializeField] private WrenchConfig _config;
    [SerializeField] private GameObject _thrownWrenchPrefab;

    private PlayerMouseAimer _aimer;
    private IPlayerVisual _animDriver;
    private ThrownWrench _airborne;
    private float _chargeTimer;
    private bool _charging;

    public bool IsCharging => _charging;
    public bool IsAirborne => _airborne != null;
    public float ChargeNormalized => _config != null && _config.throwChargeTime > 0f
        ? Mathf.Clamp01(_chargeTimer / _config.throwChargeTime)
        : 0f;

    /// <summary>
    /// World-space hand position: the billboard visual centre, so the wrench
    /// appears to leave from and return to the sprite rather than the physics root.
    /// </summary>
    public Vector3 CatchPoint =>
        _animDriver != null ? _animDriver.VisualCenter : transform.position;

    private void Awake()
    {
        _aimer      = GetComponent<PlayerMouseAimer>();
        _animDriver = GetComponent<IPlayerVisual>();
    }

    private void Update()
    {
        bool usable = PlayerInventory.Instance != null
                      && PlayerInventory.Instance.ActiveItemType == ItemType.Wrench
                      && !IsAirborne;
        if (!usable)
        {
            _charging = false;
            _chargeTimer = 0f;
            return;
        }

        if (Input.GetMouseButtonDown(1))
        {
            _charging = true;
            _chargeTimer = 0f;
        }
        else if (_charging && Input.GetMouseButton(1))
        {
            _chargeTimer += Time.deltaTime;
        }
        else if (_charging && Input.GetMouseButtonUp(1))
        {
            DoThrow();
            _charging = false;
            _chargeTimer = 0f;
        }
    }

    private void DoThrow()
    {
        // Battery cost check
        var battery = RobotBattery.Instance;
        float throwCost = battery != null && battery.Settings != null
            ? battery.Settings.throwCost : 0f;
        if (battery != null && !battery.CanSpend(throwCost)) return;

        if (_thrownWrenchPrefab == null || _config == null) return;

        // Use the billboard's visual centre as origin so distance/direction is
        // measured from where the sprite appears on screen, not from the feet.
        Vector3 origin = CatchPoint;

        // Direction on the XZ plane from the visual centre to the aim point.
        Vector3 toAim = _aimer.WorldAimPoint - origin;
        toAim.y = 0f;
        if (toAim.sqrMagnitude < 0.0001f) toAim = transform.forward;

        // Charge gates maximum reach. If the cursor is closer than that, the wrench
        // lands exactly on it; if farther, it stops at the charge-limited range.
        float maxDist = Mathf.Lerp(_config.minThrowDistance, _config.maxThrowDistance, ChargeNormalized);
        float dist = Mathf.Min(toAim.magnitude, maxDist);

        Vector3 target = origin + toAim.normalized * dist;
        // Restore the aim Y so the wrench lands at the actual world surface height.
        target.y = _aimer.WorldAimPoint.y;

        GameObject go = Instantiate(_thrownWrenchPrefab, CatchPoint, Quaternion.identity);
        _airborne = go.GetComponent<ThrownWrench>();
        if (_airborne != null) _airborne.Launch(this, target, _config);
        else Destroy(go);

        // Spend battery after successful throw
        if (battery != null && throwCost > 0f) battery.Spend(throwCost);

        // Publish throw events
        if (GameEventBus.Instance != null)
        {
            GameEventBus.Instance.Publish(new ToolThrowReleased(target, ChargeNormalized));
        }
    }

    /// <summary>Called by ThrownWrench when it has returned and been caught.</summary>
    public void OnCaught() => _airborne = null;
}

using UnityEngine;
using Flynn.Events;

/// <summary>
/// Left-click swing for the wrench multitool. Simple tap with a short cooldown
/// to prevent spam. The swing faces the mouse aim point. Routes damage through
/// the ResourceManager observer pattern. Disabled while the wrench is airborne (thrown).
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class WrenchSwingController : MonoBehaviour
{
    private const int WrenchAnimIndex = 4;

    [SerializeField] private WrenchConfig _config;
    [Tooltip("Optional — used to block swinging while the wrench is mid-throw.")]
    [SerializeField] private WrenchThrowController _throw;

    [Tooltip("Directional swipe arc visual. Fed the player→mouse direction on each swing.")]
    [SerializeField] private WrenchSwingArc _swingArc;

    [Tooltip("Cooldown between swings (seconds).")]
    [SerializeField] private float _cooldownTime = 0.1f;

    private PlayerMouseAimer _aimer;
    private PlayerInitializer _playerInit;
    private IPlayerVisual _animDriver;
    private RobotBattery _battery;
    private float _cooldown;

    public bool IsCharging => false;
    public float ChargeNormalized => 0f;

    private void Awake()
    {
        _aimer      = GetComponent<PlayerMouseAimer>();
        _animDriver = GetComponent<IPlayerVisual>();
        _playerInit = GetComponent<PlayerInitializer>();
        _battery    = RobotBattery.Instance;
    }

    private void Update()
    {
        if (_cooldown > 0f) _cooldown -= Time.deltaTime;

        bool usable = PlayerInventory.Instance != null
                      && PlayerInventory.Instance.ActiveItemType == ItemType.Wrench
                      && (_throw == null || !_throw.IsAirborne);
        if (!usable) return;

        if (Input.GetMouseButtonDown(0) && _cooldown <= 0f)
            DoSwing();
    }

    private void DoSwing()
    {
        // Battery cost check
        float swingCost = _battery != null && _battery.Settings != null
            ? _battery.Settings.swingCost : 0f;
        if (_battery != null && !_battery.CanSpend(swingCost)) return;

        if (_animDriver != null)
            _animDriver.FaceWorldDirection(_aimer.WorldAimPoint - transform.position);

        int animIndex = _aimer.SwingAnimIndex;
        if (animIndex <= 0) animIndex = WrenchAnimIndex;

        float speed = _config != null ? _config.lightSwingAnimSpeed : 1.0f;
        if (_animDriver != null)
            _animDriver.ReleaseSwing(animIndex, speed);

        if (_swingArc != null)
            _swingArc.Play(_aimer.WorldAimPoint);

        _cooldown = _cooldownTime;

        // Route hit through the ResourceManager observer pattern.
        int damage = _config != null ? _config.lightSwingDamage : 1;
        GameObject target = _aimer.HoveredGameObject;
        if (_playerInit != null && damage > 0)
            _playerInit.EmitHit(_aimer.WorldAimPoint, target, damage);

        // Publish swing event
        ToolType tool = PlayerInventory.Instance != null
            ? ToolHitContext.FromItemType(PlayerInventory.Instance.ActiveItemType)
            : ToolType.Wrench;
        PublishEvent(new ToolSwingStarted(tool, _aimer.WorldAimPoint));

        // Spend battery after successful swing
        if (_battery != null && swingCost > 0f) _battery.Spend(swingCost);
    }

    private static void PublishEvent<T>(T evt) where T : struct
    {
        if (GameEventBus.Instance != null) GameEventBus.Instance.Publish(evt);
    }
}

using UnityEngine;
using Flynn.Events;

// 2.5D force-based character controller. Moves on the XZ plane via acceleration
// toward a target velocity, so Unity physics drives interactions: PhysicMaterial
// friction (ice/mud), Rigidbody.drag (water), and AddForce zones (wind) all
// compose naturally instead of being overwritten. Small jump impulse, gravity
// handled by the Rigidbody.
[RequireComponent(typeof(Rigidbody))]
public class SolarpunkCharacterController : MonoBehaviour
{
    [SerializeField] private float moveSpeed = 5f;        // target horizontal speed under input
    [SerializeField] private float acceleration = 40f;    // how hard we drive toward target
    [SerializeField] private float jumpForce = 6f;
    // Baseline drag is 0: accel-to-target already arrests horizontal motion when input is
    // released (target velocity 0 -> decel force), so we need no passive drag — and drag is
    // isotropic, which would damp jump/fall. Water zones raise this temporarily; ice keeps it low.
    [SerializeField] private float groundDrag = 0f;
    [SerializeField] private float groundCheckDistance = 0.12f;
    [SerializeField] private LayerMask groundLayers = ~0;
    // Ice low-grip is re-asserted by the zone every physics step. Latch it for a short grace
    // window so a single missed OnTriggerStay (e.g. player center crossing the trigger edge
    // while the capsule is still on the ice) doesn't snap the ground brake back on for a step
    // and bleed the slide. Grace ends well before the player is truly off the ice.
    [SerializeField] private float lowGripGrace = 0.2f;

    public Vector3 MoveInput => moveInput;
    public bool IsGrounded => isGrounded;
    /// <summary>Horizontal speed normalized 0-1 relative to moveSpeed.</summary>
    public float NormalizedSpeed => rb != null
        ? Mathf.Clamp01(new Vector2(rb.velocity.x, rb.velocity.z).magnitude / moveSpeed)
        : 0f;

    /// <summary>Multiplies steering force each physics step. Ice sets this low (slidey, weak
    /// steering, momentum dominates) — kept &gt;0 so the player can always escape ice. Auto-resets to 1.</summary>
    public float SteeringControl { get; set; } = 1f;

    /// <summary>Multiplies the target move speed each physics step. Water/Mud set this below 1 to
    /// slow the player noticeably (lowering the target, since drag/friction barely dents accel-to-target).
    /// Auto-resets to 1.</summary>
    public float SpeedMultiplier { get; set; } = 1f;

    /// <summary>Set false each physics step by a mud zone while grounded on it: blocks jumping
    /// ("mud stops vertical movement"). Auto-resets to true.</summary>
    public bool CanJump { get; set; } = true;

    /// <summary>Set true each physics step by an ice zone: the controller stops braking toward
    /// zero when there's no input, so momentum carries (glide). Steering still applies (scaled by
    /// SteeringControl) so the player can nudge off the ice. Auto-resets to false.</summary>
    public bool LowGrip { get; set; } = false;

    public Vector3 RbVelocityDirection { get; private set; }

    private Rigidbody rb;
    private Collider bodyCollider;
    private bool isGrounded;
    private bool wasGrounded;
    private Vector3 moveInput;
    private bool jumpQueued;
    private float lowGripTimer;

    private void Awake()
    {
        rb = GetComponent<Rigidbody>();
        bodyCollider = GetComponent<Collider>();
        rb.drag = groundDrag;
        rb.freezeRotation = true;
    }

    private void Update()
    {
        moveInput.x = Input.GetAxisRaw("Horizontal");
        moveInput.z = Input.GetAxisRaw("Vertical");
        RbVelocityDirection = rb.velocity.normalized;
        if (moveInput.sqrMagnitude > 1f) moveInput.Normalize();

        if (Input.GetButtonDown("Jump")) jumpQueued = true;
    }



    private void FixedUpdate()
    {
        UpdateGrounded();

        // Accelerate toward the input-driven target velocity (XZ only). External forces
        // (wind AddForce) and surface friction are left to the solver. SpeedMultiplier
        // lowers the target (water/mud slow); SteeringControl scales the force (ice = slidey,
        // weak steering so momentum carries, but never 0 so the player can't get stuck).
        Vector3 horizVel = new Vector3(rb.velocity.x, 0f, rb.velocity.z);
        Vector3 inputDir = new Vector3(moveInput.x, 0f, moveInput.z);
        bool idle = inputDir.sqrMagnitude < 0.01f;
        // Latch low-grip: refresh the timer while the zone asserts it, otherwise decay it.
        // The brake stays off for the whole grace window, surviving single-step trigger gaps.
        if (LowGrip) lowGripTimer = lowGripGrace;
        else lowGripTimer -= Time.fixedDeltaTime;
        bool lowGrip = lowGripTimer > 0f;
        if (lowGrip)
        {
            // Ice: momentum carries, input only steers. With input, push in the input direction
            // WITHOUT the "- horizVel" brake term (that term is what kills the slide on normal
            // ground), so existing momentum is preserved and the velocity vector rotates toward
            // the input instead of being reset to it. Speed is capped to moveSpeed so the additive
            // force can't run away. Idle = no force, the frictionless surface keeps the glide.
            if (!idle)
            {
                rb.AddForce(inputDir * moveSpeed * acceleration * SteeringControl, ForceMode.Acceleration);
                Vector3 hv = new Vector3(rb.velocity.x, 0f, rb.velocity.z);
                float maxSpeed = moveSpeed * SpeedMultiplier;
                if (hv.magnitude > maxSpeed)
                {
                    hv = hv.normalized * maxSpeed;
                    rb.velocity = new Vector3(hv.x, rb.velocity.y, hv.z);
                }
            }
        }
        else
        {
            // Normal ground: accelerate toward the input-driven target velocity (XZ only).
            // SpeedMultiplier lowers the target (water/mud slow); SteeringControl scales the
            // force (wind = weak self-correction so wind blows you).
            Vector3 targetVel = inputDir * moveSpeed * SpeedMultiplier;
            Vector3 dv = targetVel - horizVel;
            rb.AddForce(dv * acceleration * SteeringControl, ForceMode.Acceleration);
        }

        if (jumpQueued && isGrounded && CanJump)
        {
            Vector3 v = rb.velocity; v.y = 0f; rb.velocity = v;
            rb.AddForce(Vector3.up * jumpForce, ForceMode.Impulse);
            isGrounded = false;
            PublishEvent(new PlayerJumped(transform.position));
        }
        jumpQueued = false;

        // Per-step terrain modifiers; zones re-assert them in OnTriggerStay (which fires
        // after FixedUpdate within the same physics step).
        SteeringControl = 1f;
        SpeedMultiplier = 1f;
        CanJump = true;
        LowGrip = false;

        // Detect landing (was airborne, now grounded).
        if (!wasGrounded && isGrounded)
            PublishEvent(new PlayerLanded(transform.position));
        wasGrounded = isGrounded;
    }

    private void UpdateGrounded()
    {
        if (bodyCollider == null)
        {
            isGrounded = false;
            return;
        }

        Vector3 origin = bodyCollider.bounds.center;
        origin.y = bodyCollider.bounds.min.y + 0.02f;

        isGrounded = Physics.Raycast(
            origin,
            Vector3.down,
            groundCheckDistance,
            groundLayers,
            QueryTriggerInteraction.Ignore
        );
    }

    private static void PublishEvent<T>(T evt) where T : struct
    {
        if (GameEventBus.Instance != null) GameEventBus.Instance.Publish(evt);
    }

#if UNITY_EDITOR
    private void OnDrawGizmosSelected()
    {
        // Ground check ray
        if (bodyCollider != null)
        {
            Vector3 origin = bodyCollider.bounds.center;
            origin.y = bodyCollider.bounds.min.y + 0.02f;
            Debug.DrawLine(origin, origin + Vector3.down * groundCheckDistance,
                isGrounded ? Color.green : Color.red);
        }

        // Velocity vector
        if (rb != null)
        {
            Debug.DrawRay(transform.position, rb.velocity, Color.cyan);
        }
    }
#endif
}

using UnityEngine;

/// <summary>
/// Push/pull objects with E. When the player grabs a <see cref="Grabbable"/>, they
/// lock onto whichever face they approached from. The object stays on the ground on
/// that side of the player while they walk — walking toward the crate pushes it,
/// walking away pulls it, walking sideways translates both. The crate never rotates
/// around the player. Press E again to release.
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class PlayerCarryController : MonoBehaviour
{
    [SerializeField] private KeyCode _grabKey = KeyCode.E;

    [Header("Push/pull positioning")]
    [Tooltip("Extra gap between the player and the held object to prevent overlap with the player's capsule.")]
    [SerializeField] private float _skinWidth = 0.15f;
    [Tooltip("How fast the held object tracks its target position.")]
    [SerializeField] private float _trackingSpeed = 20f;

    [Header("Movement")]
    [Tooltip("Speed multiplier applied to the player while carrying an object (0–1, lower = slower).")]
    [SerializeField, Range(0.1f, 1f)] private float _carrySpeedMultiplier = 0.6f;

    private PlayerMouseAimer _aimer;
    private Grabbable _heldObject;
    private Rigidbody _playerRb;
    private SolarpunkCharacterController _controller;

    // The locked hold side: unit vector from crate center toward the player at grab time,
    // snapped to the nearest cardinal axis (±X or ±Z).
    private Vector3 _holdSide;

    // Distance from the player center to the crate center along the hold-side axis.
    private float _holdDistance;

    // The crate's ground Y so it stays on the floor.
    private float _crateGroundY;

    /// <summary>True while carrying an object.</summary>
    public bool IsCarrying => _heldObject != null;

    private void Awake()
    {
        _aimer = GetComponent<PlayerMouseAimer>();
        _playerRb = GetComponent<Rigidbody>();
        _controller = GetComponent<SolarpunkCharacterController>();
    }

    private void Update()
    {
        if (!Input.GetKeyDown(_grabKey)) return;

        if (IsCarrying)
        {
            Release();
            return;
        }

        Grabbable target = FindGrabbableTarget();
        if (target != null && !target.IsHeld)
            Grab(target);
    }

    private void LateUpdate()
    {
        if (!IsCarrying || _heldObject == null) return;

        // Position the crate on the locked hold side of the player.
        Vector3 playerPos = transform.position;
        Vector3 crateTarget = playerPos - _holdSide * _holdDistance;
        crateTarget.y = _crateGroundY;

        _heldObject.transform.position = Vector3.Lerp(
            _heldObject.transform.position, crateTarget, _trackingSpeed * Time.deltaTime);

        // Keep the crate upright and unmoving rotationally
        _heldObject.transform.rotation = Quaternion.identity;
    }

    private void FixedUpdate()
    {
        // Slow the player while carrying
        if (_controller != null && IsCarrying)
            _controller.SpeedMultiplier = _carrySpeedMultiplier;
    }

    /// <summary>Find a Grabbable under the cursor within interaction range.</summary>
    private Grabbable FindGrabbableTarget()
    {
        if (_aimer == null) return null;

        IInteractionPromptProvider interactable = _aimer.HoveredInteractable;
        if (interactable is Grabbable grabbable)
            return grabbable;

        GameObject hovered = _aimer.HoveredGameObject;
        if (hovered != null)
        {
            Grabbable g = hovered.GetComponentInParent<Grabbable>();
            if (g != null)
            {
                float dist = Vector3.Distance(transform.position, g.transform.position);
                if (dist <= _aimer.InteractionRange)
                    return g;
            }
        }

        return null;
    }

    private void Grab(Grabbable target)
    {
        _heldObject = target;

        // Determine which face the player is on
        Vector3 toPlayer = transform.position - target.transform.position;
        toPlayer.y = 0f;
        _holdSide = SnapToCardinal(toPlayer);

        // Calculate the hold distance: player half-extent + crate half-extent + skin.
        // The skin width keeps the player's capsule clearly outside the crate so
        // the physics solver never sees an overlap.
        float playerRadius = 0.23f;
        float crateExtent = GetExtentsAlong(target, _holdSide);
        _holdDistance = playerRadius + crateExtent + _skinWidth;

        // Remember the crate's Y so it stays grounded
        _crateGroundY = target.transform.position.y;

        _heldObject.OnGrab();
    }

    private void Release()
    {
        if (_heldObject == null) return;

        _heldObject.OnRelease();
        _heldObject = null;

        if (_controller != null) _controller.SpeedMultiplier = 1f;
    }

    /// <summary>
    /// Force-release the carried object (e.g. if it's destroyed or the player enters
    /// a state where carrying isn't allowed). Called externally.
    /// </summary>
    public void ForceRelease()
    {
        if (_heldObject != null) _heldObject.OnRelease();
        _heldObject = null;
        if (_controller != null) _controller.SpeedMultiplier = 1f;
    }

    private static Vector3 SnapToCardinal(Vector3 dir)
    {
        if (dir.sqrMagnitude < 0.001f) return Vector3.right;

        float absX = Mathf.Abs(dir.x);
        float absZ = Mathf.Abs(dir.z);

        if (absX >= absZ)
            return new Vector3(Mathf.Sign(dir.x), 0f, 0f);
        else
            return new Vector3(0f, 0f, Mathf.Sign(dir.z));
    }

    private static float GetExtentsAlong(Grabbable target, Vector3 axis)
    {
        Collider col = target.GetComponent<Collider>();
        if (col != null)
        {
            if (Mathf.Abs(axis.x) > 0.5f) return col.bounds.extents.x;
            if (Mathf.Abs(axis.z) > 0.5f) return col.bounds.extents.z;
        }
        return 0.5f;
    }
}

using UnityEngine;
using Flynn.Events;

/// <summary>
/// Wrench grapple with swing physics. Hold Q to charge, release to fire.
/// A hook projectile travels from the player's visual center to the target,
/// then the player swings on the rope with pendulum physics (momentum preservation
/// on release). Grapples what the cursor is over (resolved by PlayerMouseAimer):
///   - RopeAnchor → swing the player around the anchor point
///   - RopePullable → reel the object toward the player
/// Blocked while on mud. Requires the wrench as the active item.
/// </summary>
[RequireComponent(typeof(PlayerMouseAimer))]
public class RopeLassoController : MonoBehaviour
{
    [SerializeField] private RopeLassoConfig _config;
    [Tooltip("Rope visual. A child LineRenderer; enabled only while grappling.")]
    [SerializeField] private LineRenderer _ropeLine;

    private PlayerMouseAimer _aimer;
    private IPlayerVisual _animDriver;
    private SolarpunkCharacterController _controller;
    private TerrainStateAggregator _terrainState;
    private Rigidbody _rb;
    private PlayerCarryController _carry;

    // ── Charge ──────────────────────────────────────────────────────────────

    private float _chargeTimer;
    private bool _charging;

    // ── State machine ───────────────────────────────────────────────────────

    private enum GrappleState { Idle, Firing, Swinging, PullingObject }
    private GrappleState _state = GrappleState.Idle;

    // Firing state
    private Vector3 _fireStart;
    private Vector3 _fireTarget;
    private float _fireElapsed;

    // Swing state
    private Vector3 _anchorPoint;
    private float _ropeLength;
    private float _swingElapsed;

    // Pull state
    private Rigidbody _pullBody;
    private float _pullElapsed;

    // Rope visual
    private const int RopeSegments = 10;
    private Vector3[] _ropePoints;

    // Cached for end-event publishing
    private RopeAnchor _activeAnchor;
    private RopePullable _activePullable;

    // Actual world-space anchor (for visual), separate from the Y-projected _anchorPoint
    private Vector3 _anchorWorldPos;

    // ── Public API ──────────────────────────────────────────────────────────

    public bool IsCharging => _charging;
    public float ChargeNormalized => _config != null && _config.chargeTime > 0f
        ? Mathf.Clamp01(_chargeTimer / _config.chargeTime) : 0f;
    public bool IsPulling => _state == GrappleState.Swinging || _state == GrappleState.PullingObject;
    public bool IsSwinging => _state == GrappleState.Swinging;

    /// <summary>
    /// Billboard visual centre — the rope leaves from the sprite's centre, not the feet.
    /// Uses the IPlayerVisual.VisualCenter which accounts for camera-tilt offset on
    /// the billboarded sprite.
    /// </summary>
    public Vector3 HandPoint => _animDriver != null ? _animDriver.VisualCenter : transform.position;

    // ── Awake ───────────────────────────────────────────────────────────────

    private void Awake()
    {
        _aimer      = GetComponent<PlayerMouseAimer>();
        _animDriver = GetComponent<IPlayerVisual>();
        _controller = GetComponent<SolarpunkCharacterController>();
        _terrainState = GetComponent<TerrainStateAggregator>();
        _rb         = GetComponent<Rigidbody>();
        _carry      = GetComponent<PlayerCarryController>();

        _ropePoints = new Vector3[RopeSegments];

        if (_ropeLine != null)
        {
            _ropeLine.positionCount = RopeSegments;
            _ropeLine.enabled = false;
        }
    }

    // ── Update: input, charging, firing progress ────────────────────────────

    private void Update()
    {
        switch (_state)
        {
            case GrappleState.Idle:
                UpdateIdle();
                break;
            case GrappleState.Firing:
                UpdateFiring();
                break;
            case GrappleState.Swinging:
                UpdateSwingInput();
                break;
            case GrappleState.PullingObject:
                UpdatePullInput();
                break;
        }
    }

    private void UpdateIdle()
    {
        bool onMud = _terrainState != null
            ? _terrainState.CurrentTerrainState.BlocksRope
            : (_controller != null && !_controller.CanJump);
        bool usable = PlayerInventory.Instance != null
                      && PlayerInventory.Instance.ActiveItemType == ItemType.Wrench
                      && !onMud
                      && (_carry == null || !_carry.IsCarrying);
        if (!usable)
        {
            _charging = false;
            _chargeTimer = 0f;
            return;
        }

        if (Input.GetKeyDown(KeyCode.Q))
        {
            _charging = true;
            _chargeTimer = 0f;
        }
        else if (_charging && Input.GetKey(KeyCode.Q))
        {
            _chargeTimer += Time.deltaTime;
        }
        else if (_charging && Input.GetKeyUp(KeyCode.Q))
        {
            FireLasso();
            _charging = false;
            _chargeTimer = 0f;
        }
    }

    private void UpdateFiring()
    {
        _fireElapsed += Time.deltaTime;
        float fireDuration = _config != null ? _config.hookTravelTime : 0.12f;
        float t = Mathf.Clamp01(_fireElapsed / fireDuration);

        // Ease-out for a snappy travel feel
        float easedT = 1f - Mathf.Pow(1f - t, 3f);
        Vector3 hookPos = Vector3.Lerp(_fireStart, _fireTarget, easedT);

        // Draw extending rope from hand to hook tip (sag fades as hook approaches target)
        DrawRope(HandPoint, hookPos, slack: 0.4f * (1f - t));

        if (t >= 1f)
        {
            if (_activePullable != null)
                StartPullingObject();
            else
                StartSwinging();
        }
    }

    private void UpdateSwingInput()
    {
        // Release with Jump or Q
        if (Input.GetButtonDown("Jump") || Input.GetKeyDown(KeyCode.Q))
        {
            EndGrapple(preserveMomentum: true);
            return;
        }

        // Adjust rope length with scroll wheel
        if (_config != null)
        {
            float scroll = Input.mouseScrollDelta.y;
            if (scroll != 0f)
            {
                _ropeLength -= scroll * _config.ropeAdjustSpeed * Time.deltaTime;
                _ropeLength = Mathf.Clamp(_ropeLength, _config.minRopeLength, _config.maxRopeLength);
            }
        }
    }

    private void UpdatePullInput()
    {
        // Release pull with Q
        if (Input.GetKeyUp(KeyCode.Q))
            EndGrapple(preserveMomentum: false);
    }

    // ── Fire ────────────────────────────────────────────────────────────────

    private void FireLasso()
    {
        if (_config == null) return;

        RopeAnchor anchor = _aimer.HoveredAnchor;
        RopePullable pullable = _aimer.HoveredPullable;
        if (anchor == null && pullable == null) return;

        Vector3 grapplePoint = _aimer.HoveredGrapplePoint;
        float dist = Vector3.Distance(HandPoint, grapplePoint);
        if (dist < _config.minRange || dist > _config.maxRange) return;

        // Battery check
        var battery = RobotBattery.Instance;
        float grappleCost = battery != null && battery.Settings != null
            ? battery.Settings.grappleCost : 0f;
        if (battery != null && !battery.CanSpend(grappleCost)) return;
        if (battery != null && grappleCost > 0f) battery.Spend(grappleCost);

        // Cache targets for events
        _activeAnchor = anchor;
        _activePullable = pullable;

        // Start firing
        _state = GrappleState.Firing;
        _fireStart = HandPoint;
        _fireTarget = grapplePoint;
        _fireElapsed = 0f;

        // Face the target
        if (_animDriver != null) _animDriver.FaceWorldDirection(grapplePoint - transform.position);

        // Publish start event immediately
        if (GameEventBus.Instance != null)
        {
            if (pullable != null)
                GameEventBus.Instance.Publish(new RopePullStarted(pullable));
            else if (anchor != null)
                GameEventBus.Instance.Publish(new RopeGrappleStarted(anchor));
        }
    }

    // ── State transitions ───────────────────────────────────────────────────

    private void StartSwinging()
    {
        _state = GrappleState.Swinging;
        _swingElapsed = 0f;

        // 2.5D: project the anchor onto the player's Y so the tether is horizontal-only.
        // The rope constrains on the XZ plane; Y is entirely gravity/jump controlled.
        _anchorPoint = new Vector3(_fireTarget.x, _rb.position.y, _fireTarget.z);
        _anchorWorldPos = _fireTarget;

        // Rope length = initial horizontal distance to anchor
        Vector3 toAnchorXZ = _anchorPoint - _rb.position;
        toAnchorXZ.y = 0f;
        _ropeLength = toAnchorXZ.magnitude;
        if (_config != null)
            _ropeLength = Mathf.Clamp(_ropeLength, _config.minRopeLength, _config.maxRopeLength);

        // Snap impulse toward anchor on XZ only (no vertical yank)
        if (_config != null && _config.snapForce > 0f && _rb != null)
        {
            Vector3 toAnchor = (_anchorPoint - _rb.position);
            toAnchor.y = 0f;
            if (toAnchor.sqrMagnitude > 0.01f)
                _rb.AddForce(toAnchor.normalized * _config.snapForce, ForceMode.Impulse);
        }

        // Suppress character controller so it doesn't fight the swing
        if (_controller != null) _controller.SteeringControl = 0f;
    }

    private void StartPullingObject()
    {
        _state = GrappleState.PullingObject;
        _pullBody = _activePullable != null ? _activePullable.Body : null;
        _pullElapsed = 0f;

        if (_pullBody == null) { EndGrapple(false); return; }
    }

    // ── FixedUpdate: swing & pull physics ────────────────────────────────────

    private void FixedUpdate()
    {
        switch (_state)
        {
            case GrappleState.Swinging:
                UpdateSwingPhysics();
                break;
            case GrappleState.PullingObject:
                UpdatePullPhysics();
                break;
        }
    }

    private void UpdateSwingPhysics()
    {
        if (_rb == null) { EndGrapple(false); return; }

        _swingElapsed += Time.fixedDeltaTime;

        // Safety timeout
        if (_config != null && _swingElapsed >= _config.pullTimeout)
        {
            EndGrapple(true);
            return;
        }

        // Battery drain while swinging
        var battery = RobotBattery.Instance;
        if (battery != null && battery.Settings != null && battery.Settings.pullCostPerSecond > 0f)
        {
            battery.DrainOverTime(battery.Settings.pullCostPerSecond);
            if (battery.IsEmpty) { EndGrapple(true); return; }
        }

        // 2.5D: re-project anchor to player's Y each step so the tether stays horizontal
        // even as the player rises/falls from gravity and jumps.
        _anchorPoint = new Vector3(_anchorPoint.x, _rb.position.y, _anchorPoint.z);

        // Swing input: WASD adds tangential force on the XZ plane to pump the swing
        Vector3 inputDir = new Vector3(
            Input.GetAxisRaw("Horizontal"), 0f, Input.GetAxisRaw("Vertical")).normalized;
        if (inputDir.sqrMagnitude > 0.01f)
        {
            Vector3 toAnchorXZ = (_anchorPoint - _rb.position);
            toAnchorXZ.y = 0f;
            if (toAnchorXZ.sqrMagnitude > 0.001f)
            {
                toAnchorXZ.Normalize();
                // Tangent on XZ: perpendicular to the rope direction
                Vector3 tangent = inputDir - Vector3.Project(inputDir, toAnchorXZ);
                tangent.y = 0f;
                if (tangent.sqrMagnitude > 0.001f)
                {
                    tangent.Normalize();
                    float swingForce = _config != null ? _config.swingForce : 30f;
                    _rb.AddForce(tangent * swingForce, ForceMode.Acceleration);
                }
            }
        }

        // 2.5D: enforce rope length constraint on the XZ plane only.
        // Y is untouched — gravity and jumps work normally while tethered.
        Vector3 toAnchorVec = _anchorPoint - _rb.position;
        toAnchorVec.y = 0f;
        float currentDistXZ = toAnchorVec.magnitude;

        if (currentDistXZ > _ropeLength && currentDistXZ > 0.001f)
        {
            Vector3 dirXZ = toAnchorVec.normalized;

            // Correct XZ position to stay on the horizontal rope circle
            Vector3 corrected = _rb.position;
            corrected.x = _anchorPoint.x - dirXZ.x * _ropeLength;
            corrected.z = _anchorPoint.z - dirXZ.z * _ropeLength;
            _rb.position = corrected;

            // Remove outward radial XZ velocity (keep tangential + all Y velocity)
            Vector3 outwardXZ = new Vector3(-dirXZ.x, 0f, -dirXZ.z);
            float vOut = Vector3.Dot(new Vector3(_rb.velocity.x, 0f, _rb.velocity.z), outwardXZ);
            if (vOut > 0f)
            {
                Vector3 correction = outwardXZ * vOut;
                _rb.velocity -= correction;
            }

            // Cap XZ swing speed only (Y is free)
            Vector3 velXZ = new Vector3(_rb.velocity.x, 0f, _rb.velocity.z);
            if (_config != null && velXZ.magnitude > _config.maxSwingSpeed)
            {
                velXZ = velXZ.normalized * _config.maxSwingSpeed;
                _rb.velocity = new Vector3(velXZ.x, _rb.velocity.y, velXZ.z);
            }
        }

        // Suppress character controller each step (it auto-resets to 1)
        if (_controller != null) _controller.SteeringControl = 0f;
    }

    private void UpdatePullPhysics()
    {
        if (_pullBody == null) { EndGrapple(false); return; }

        _pullElapsed += Time.fixedDeltaTime;
        if (_config != null && _pullElapsed >= _config.pullTimeout)
        {
            EndGrapple(false);
            return;
        }

        // Battery drain while pulling
        var battery = RobotBattery.Instance;
        if (battery != null && battery.Settings != null && battery.Settings.pullCostPerSecond > 0f)
        {
            battery.DrainOverTime(battery.Settings.pullCostPerSecond);
            if (battery.IsEmpty) { EndGrapple(false); return; }
        }

        // Pull the object toward the player's hand
        Vector3 target = HandPoint;
        Vector3 to = target - _pullBody.position;

        float stopRadius = _config != null ? _config.stopRadius : 0.8f;
        if (to.magnitude <= stopRadius)
        {
            EndGrapple(false);
            return;
        }

        float pullForce = _config != null ? _config.pullForce : 55f;
        float maxPullSpeed = _config != null ? _config.maxPullSpeed : 14f;

        _pullBody.AddForce(to.normalized * pullForce, ForceMode.Acceleration);
        if (_pullBody.velocity.magnitude > maxPullSpeed)
            _pullBody.velocity = _pullBody.velocity.normalized * maxPullSpeed;
    }

    // ── End grapple ─────────────────────────────────────────────────────────

    private void EndGrapple(bool preserveMomentum)
    {
        // Publish end events
        if (GameEventBus.Instance != null)
        {
            if (_activeAnchor != null)
                GameEventBus.Instance.Publish(new RopeGrappleEnded(_activeAnchor));
            if (_activePullable != null)
                GameEventBus.Instance.Publish(new RopePullEnded(_activePullable));
        }

        // 2.5D: on swing release, just let momentum carry — no forced vertical boost.
        // The player keeps their current XZ swing velocity (tangential) plus whatever
        // Y velocity they have from gravity/jumps.

        // Restore character controller
        if (_controller != null) _controller.SteeringControl = 1f;

        _state = GrappleState.Idle;
        _pullBody = null;
        _swingElapsed = 0f;
        _pullElapsed = 0f;
        _activeAnchor = null;
        _activePullable = null;
    }

    // ── LateUpdate: rope visual ─────────────────────────────────────────────

    private void LateUpdate()
    {
        if (_ropeLine == null) return;

        switch (_state)
        {
            case GrappleState.Swinging:
                // Taut rope from hand to the actual world anchor (not Y-projected)
                DrawRope(HandPoint, _anchorWorldPos, slack: 0.02f);
                break;

            case GrappleState.PullingObject:
                if (_pullBody != null)
                    DrawRope(HandPoint, _pullBody.position, slack: 0.08f);
                else
                    _ropeLine.enabled = false;
                break;

            case GrappleState.Firing:
                // Handled in UpdateFiring
                break;

            default:
                _ropeLine.enabled = false;
                break;
        }
    }

    // ── Rope drawing with sag ───────────────────────────────────────────────

    /// <summary>
    /// Draw the rope from start to end with a parabolic sag.
    /// slack=0 → taut straight line; slack=0.3 → visible droop.
    /// </summary>
    private void DrawRope(Vector3 start, Vector3 end, float slack)
    {
        if (_ropeLine == null) return;

        _ropeLine.enabled = true;

        float dist = Vector3.Distance(start, end);

        for (int i = 0; i < RopeSegments; i++)
        {
            float t = (float)i / (RopeSegments - 1);
            Vector3 point = Vector3.Lerp(start, end, t);

            // Parabolic sag: max at middle, zero at ends
            float sagAmount = slack * 4f * t * (1f - t) * dist;
            point += Vector3.down * sagAmount;

            _ropePoints[i] = point;
        }

        _ropeLine.SetPositions(_ropePoints);
    }
}

using UnityEngine;
using Flynn.Events;

/// <summary>
/// Projectile spawned by WrenchThrowController. Flies outbound to a target point,
/// hovers (returnDelay), then homes back to the thrower like a boomerang and is caught.
/// Spins a child visual for the boomerang look. On impact with a ResourceNode,
/// applies throw damage through the effectiveness system.
/// </summary>
public class ThrownWrench : MonoBehaviour
{
    private enum Phase { Outbound, Hover, Returning }

    private WrenchThrowController _owner;
    private WrenchConfig _config;
    private Vector3 _target;
    private Phase _phase;
    private float _hoverTimer;
    private Transform _spin;
    private Camera _cam;
    private float _roll;
    private bool _hasHitTarget;

    public void Launch(WrenchThrowController owner, Vector3 target, WrenchConfig config)
    {
        _owner   = owner;
        _target  = target;
        _config  = config;
        _phase   = Phase.Outbound;
        _spin    = transform.childCount > 0 ? transform.GetChild(0) : transform;
    }

    private void Update()
    {
        if (_config == null) return;

        switch (_phase)
        {
            case Phase.Outbound:
                MoveToward(_target, _config.throwSpeed);
                if (Reached(_target, 0.1f))
                {
                    _phase = Phase.Hover;
                    _hoverTimer = _config.returnDelay;
                }
                break;

            case Phase.Hover:
                _hoverTimer -= Time.deltaTime;
                if (_hoverTimer <= 0f) _phase = Phase.Returning;
                break;

            case Phase.Returning:
                Vector3 catchPoint = _owner != null ? _owner.CatchPoint : transform.position;
                MoveToward(catchPoint, _config.returnSpeed);
                if (Reached(catchPoint, _config.catchRadius))
                {
                    if (_owner != null) _owner.OnCaught();
                    Destroy(gameObject);
                }
                break;
        }
    }

    /// <summary>
    /// Detect collision with ResourceNodes during the outbound phase.
    /// Uses the effectiveness system to determine damage.
    /// </summary>
    private void OnCollisionEnter(Collision collision)
    {
        if (_phase != Phase.Outbound || _hasHitTarget) return;

        ResourceNode node = collision.gameObject.GetComponentInParent<ResourceNode>();
        if (node == null) return;

        _hasHitTarget = true;

        ToolType tool = PlayerInventory.Instance != null
            ? ToolHitContext.FromItemType(PlayerInventory.Instance.ActiveItemType)
            : ToolType.Wrench;

        int damage = _config != null ? _config.heavySwingDamage : 2;
        Vector3 hitDir = (collision.transform.position - transform.position).normalized;

        var hit = new ToolHitContext(
            source: gameObject,
            toolType: tool,
            action: ToolActionType.Throw,
            damage: damage,
            hitPoint: collision.contacts.Length > 0 ? collision.contacts[0].point : transform.position,
            hitDirection: hitDir,
            charge: 1f
        );

        node.TryApplyToolHit(hit);

        // Immediately start returning after impact
        _phase = Phase.Returning;
    }

    // Billboard the visual to the camera (like the player sprite) and spin it in the
    // screen plane so the boomerang reads as rotating regardless of view angle.
    private void LateUpdate()
    {
        if (_config == null || _spin == null) return;
        if (_cam == null) _cam = Camera.main;
        if (_cam == null) return;

        _roll += _config.spinSpeed * Time.deltaTime;
        _spin.rotation = _cam.transform.rotation * Quaternion.Euler(0f, 0f, _roll);
    }

    private void MoveToward(Vector3 p, float speed)
        => transform.position = Vector3.MoveTowards(transform.position, p, speed * Time.deltaTime);

    private bool Reached(Vector3 p, float radius)
        => (transform.position - p).sqrMagnitude <= radius * radius;
}

